action.customFunction:
let $injector = widgetContext.$scope.$injector;
let customDialog = $injector.get(widgetContext.servicesMap.get('customDialog'));
let params = widgetContext.stateController.getStateParams();

customDialog.customDialog(htmlTemplate, ZoneDialogController).subscribe();

function ZoneDialogController(instance) {
    let vm = instance;
    vm.self = vm;
    vm.zoneData = {
        ctx: widgetContext,
        companyId: params.company ? params.company.entityId : null,
        perimeter: additionalParams.coordinates
    };
}

label.patternFunction:
let COLLAR_ID_KEY = 'collarId';

let value = null;
let rows = [data].concat(dsData || []);

for (let i = 0; i < rows.length; i++) {
    let row = rows[i];
    if (!row || row.entityId !== data.entityId) {
        continue;
    }
    let rowValue = row[COLLAR_ID_KEY];
    if (rowValue === undefined || rowValue === null || rowValue === '') {
        continue;
    }
    value = rowValue;
}

return value || data.deviceName;

