markerImage.imageFunction:
let MOVEMENT_ABSENT_KEY = 'movementAbsent';
let MARKER_SIZE = 34;

let value = null;
let valueTs = -1;
let rows = [data].concat(dsData || []);

for (let i = 0; i < rows.length; i++) {
    let row = rows[i];
    if (!row || row.entityId !== data.entityId) {
        continue;
    }
    let rowValue = row[MOVEMENT_ABSENT_KEY];
    if (rowValue === undefined || rowValue === null || rowValue === '') {
        continue;
    }
    let rowTs = row[MOVEMENT_ABSENT_KEY + '|ts'] || 0;
    if (rowTs >= valueTs) {
        value = rowValue;
        valueTs = rowTs;
    }
}

let movementAbsent = value === true || value === 'true';

return {
    url: images[movementAbsent ? 2 : 0] || images[0],
    size: MARKER_SIZE
};

